using HakutaiKagami.Core.Messaging;
namespace HakutaiKagami.Core.Contracts;
public sealed record DelegationTerms(EntityId Owner,EntityId Principal,EntityId Agent,EntityId Recipient,EntityId Army,EntityId[] Units,RegionalAction[] Actions,long From,long Until,EntityId Basis,FieldPoint KnownAddress);
public sealed record DelegatedUnitPlan(EntityId Unit,FieldPoint Origin,FieldPoint Goal,FieldLeg[] Route);
public sealed record DelegationPlan(EntityId Directive,long At,DelegatedUnitPlan[] Units);
public sealed record DelegatedUnitReport(EntityId Unit,FieldPoint Position,FieldPoint Heading,int Soldiers,int Morale);
public sealed record DelegationArrival(EntityId Directive,long At,string Message,DelegatedUnitReport[] Units);
public sealed record DelegationState(DelegationTerms Terms,DelegationPlan[] Plans,DelegationArrival[] Arrivals);
public sealed record DelegationRow(EntityId Directive,string Receipt,string Progress,string Responsibility,long? ReportedAt);
public static class DelegationMission
{
    public const string Ruleset="created-retainer-delegation-v1",Contract="other-house-signed-limited-linear-plans-physical-receipt-and-arrival-self-report-v1",ArrivalKind="region-arrival";
    public static readonly EntityId Owner=new("org:house"),Army=new("army:clerk"),Basis=new("basis:joint-field-delegation"),Mandate=new("mandate:joint-field/clerk");
    public static EntityId[] Units=>[new("unit:clerk"),new("unit:region/1/1"),new("unit:region/1/2")];
    public static bool Enabled(ContractWorld w)=>w.Definitions.Ruleset==Ruleset;
    public static DelegationTerms Terms(long until)=>new(Owner,ContractFixture.Lord,PersonalStart.Person,ContractFixture.Clerk,Army,Units,[RegionalAction.Move,RegionalAction.Hold,RegionalAction.Retreat],0,until,Basis,ContinuousWorld.Point("castle",95000,-50000));
    static CommandMandate Grant(DelegationTerms t)=>new(Mandate,t.Principal,t.Agent,t.Army,t.Units,t.Actions,t.Basis,t.From,t.Until);
    public static ContractWorld Create(string name="作成武将",ulong seed=20261020,bool refuses=false,long until=long.MaxValue){if(until<=0)throw new InvalidDataException("Invalid delegation period");var w=FieldPresence.Create(name,seed);w.WorldId=new("world:"+Ruleset);w.Definitions=w.Definitions with{Id=new("scenario:"+Ruleset),Ruleset=Ruleset,AuthorityBases=[..w.Definitions.AuthorityBases,new(Basis,"他家主権者の架空の共同演習合意。所有/主従を保つ配置・保持・帰還の一時指揮。交戦/再委任不可")]};w.Delegation=new(Terms(until),[],[]);w.CommandMandates=[..w.CommandMandates!,Grant(w.Delegation.Terms)];w.Presence=w.Presence! with{Terms=FieldPresence.ExpectedTerms(w)};w.Region=w.Region! with{Refuses=refuses,Units=w.Region.Units.Select(u=>u.Commander==ContractFixture.Clerk?u with{Position=u.Home,RouteOrigin=u.Home,Goal=u.Home,Route=[],Phase="standing"}:u).ToArray()};w.Characters=w.Characters.Select(c=>c.Id==ContractFixture.Clerk?c with{WillObey=!refuses}:c).ToArray();foreach(var observer in new[]{w.PlayerControl,ContractFixture.Clerk,ContractFixture.Lord,RetainerStart.Lord}){var id=new EntityId("evidence:joint-command/"+observer.Value.Replace(':','/'));w.Evidence=[..w.Evidence,new(id,observer,ContractFixture.Clerk,"joint-training-command-and-known-camp",0,0,null,null)];w.Knowledge=[..w.Knowledge,new(observer,id,0)];}w.Definitions=w.Definitions with{Version=RegionalBattle.Version(w)};RegionalBattle.Sync(w);ContractValidation.Validate(w);if(!StartConfiguration.Check(w,StartConfiguration.Describe(w,w.PlayerControl,StartTemplate.Retainer,PersonOrigin.Created,CreatedCampaign.Policy),CreatedCampaign.Policy).Eligible)throw new InvalidDataException("Delegation start budget invalid");return w;}
    public static bool Remote(ContractWorld w,RegionalRequest r)=>Enabled(w)&&r.Actor==w.PlayerControl&&r.Recipient==ContractFixture.Clerk;
    public static bool CanCommand(ContractWorld w,RegionalRequest r,long at){if(!Remote(w,r))return false;var t=w.Delegation!.Terms;return t.Actions.Contains(r.Action)&&(t.From<=at&&at<t.Until||r.Action==RegionalAction.Retreat&&w.Region!.Commands.Any(c=>Remote(w,c.Request)&&c.IssuedAt<t.Until))&&t.Units.All(id=>w.Units.Any(u=>u.Id==id&&u.Army==t.Army&&u.Commander==t.Recipient&&u.Organization==t.Owner));}
    public static FieldPoint? InitialAddress(ContractWorld w,EntityId observer,EntityId recipient)=>Enabled(w)&&observer==w.PlayerControl&&recipient==ContractFixture.Clerk&&w.Evidence.Any(e=>e.Observer==observer&&e.Claim=="joint-training-command-and-known-camp")?w.Delegation!.Terms.KnownAddress:null;
    public static RegionalRequest Build(ContractWorld w,string id,RegionalAction action){var existing=w.Region!.Commands.SingleOrDefault(c=>c.Request.Id==new EntityId(id));if(existing!=null&&existing.Request.Action==action)return existing.Request;var prior=w.Region.Commands.LastOrDefault(c=>Remote(w,c.Request));return new(new(id),w.PlayerControl,ContractFixture.Clerk,action,ContinuousWorld.Point("castle",195000,-85000),ContinuousWorld.Point("castle",215000,-85000),prior?.Request.Id);}
    internal static void ValidateIssue(ContractWorld w,RegionalRequest r){if(!Remote(w,r))return;var prior=w.Region!.Commands.LastOrDefault(c=>Remote(w,c.Request));if(r.Supersedes!=prior?.Request.Id)throw new InvalidDataException("Replacement must name the last locally issued plan");}
    public static bool Replaces(ContractWorld w,EntityId child,EntityId ancestor){var visited=new HashSet<EntityId>();var id=(EntityId?)child;while(id is {} current&&visited.Add(current)){var c=w.Region!.Commands.SingleOrDefault(c=>c.Request.Id==current);id=c?.Request.Supersedes;if(id==ancestor)return true;}return false;}
    internal static bool HasAppliedReplacement(ContractWorld w,EntityId id)=>w.Region!.Commands.Any(c=>c.AppliedAt!=null&&Replaces(w,c.Request.Id,id));
    internal static void RecordPlan(ContractWorld w,RegionalCommand c){if(!Remote(w,c.Request)||c.Result!="applied")return;if(w.Delegation!.Plans.Any(p=>p.Directive==c.Request.Id))throw new InvalidDataException("Directive executed twice");w.Delegation=w.Delegation with{Plans=[..w.Delegation.Plans,new(c.Request.Id,w.ElapsedSeconds,Units.Select(id=>{var u=w.Region!.Units.Single(u=>u.Id==id);return new DelegatedUnitPlan(id,u.RouteOrigin,u.Goal,u.Route);}).ToArray())]};}
    static string Message(EntityId id)=>"message:delegation-arrival/"+ContractJson.Hash(System.Text.Encoding.UTF8.GetBytes(id.Value));
    static string Body(DelegationArrival r)=>System.Text.Encoding.UTF8.GetString(ContractJson.Write(r.Units));
    internal static void Update(ContractWorld w){if(!Enabled(w))return;var c=w.Region!.Commands.LastOrDefault(c=>Remote(w,c.Request)&&c.Result=="applied");if(c==null||w.Delegation!.Arrivals.Any(r=>r.Directive==c.Request.Id))return;var plan=w.Delegation.Plans.Single(p=>p.Directive==c.Request.Id);if(plan.Units.Any(p=>!w.Region.Units.Any(u=>u.Id==p.Unit&&u.Soldiers>0&&u.Position==p.Goal&&!u.Route.Any(l=>l.EndAt>w.ElapsedSeconds))))return;var report=new DelegationArrival(c.Request.Id,w.ElapsedSeconds,Message(c.Request.Id),Units.Select(id=>{var u=w.Region.Units.Single(u=>u.Id==id);return new DelegatedUnitReport(id,u.Position,u.Heading,u.Soldiers,u.Morale);}).ToArray());var original=DelegationTransport.ReturnDelivery(w,c.Message);RegionalBattle.Send(w,new(report.Message,c.Request.Id.Value,ArrivalKind,c.Request.Recipient.Value,c.Request.Actor.Value,Body(report),ContractFixture.Castle.Value,w.ElapsedSeconds),RegionalBattle.Position(w,c.Request.Recipient),original.Origin);w.Delegation=w.Delegation with{Arrivals=[..w.Delegation.Arrivals,report]};}
    public static RegionalView[] MergeReports(ContractWorld w,EntityId observer,RegionalView[] direct){if(!Enabled(w)||observer!=w.PlayerControl)return direct;var list=direct.ToList();foreach(var report in w.Delegation!.Arrivals.Where(r=>MessageFlow.Knows(w.Messaging,r.Message,observer.Value)).OrderBy(r=>r.At))foreach(var u in report.Units){if(list.Any(v=>v.Unit==u.Unit&&v.ObservedAt>=report.At))continue;list.RemoveAll(v=>v.Unit==u.Unit);list.Add(new(u.Unit,u.Position,u.Heading,RegionalGround.Height(u.Position,true,true),u.Soldiers,u.Morale,"standing",report.At,false));}return list.ToArray();}
    public static DelegationRow[] View(WorldSession session,EntityId observer){var w=session.DiagnosticSnapshot();if(!Enabled(w)||observer!=w.PlayerControl)return [];return w.Region!.Commands.Where(c=>Remote(w,c.Request)).Select(c=>{var r=w.Delegation!.Arrivals.SingleOrDefault(r=>r.Directive==c.Request.Id&&MessageFlow.Knows(w.Messaging,r.Message,observer.Value));return new DelegationRow(c.Request.Id,RegionalBattle.Status(w,c,observer),r==null?"到達の返報は未確認":c.Request.Action==RegionalAction.Retreat?"帰還到達の申告":"配置到達の申告","責任・処分は未審査",r?.At);}).ToArray();}
    public static void Validate(ContractWorld w){if(!Enabled(w))return;var s=w.Delegation??throw new InvalidDataException("Missing delegation module");if(s.Terms.Until<=0||ContractJson.CanonicalHash(s.Terms)!=ContractJson.CanonicalHash(Terms(s.Terms.Until))||w.CommandMandates!.Length!=2||ContractJson.CanonicalHash(w.CommandMandates[1])!=ContractJson.CanonicalHash(Grant(s.Terms))||!w.Definitions.AuthorityBases.Any(b=>b.Id==Basis)||!w.Definitions.Armies.Any(a=>a.Id==Army&&a.Organization==Owner&&a.Commander==ContractFixture.Clerk)||Units.Any(id=>!w.Units.Any(u=>u.Id==id&&u.Army==Army&&u.Organization==Owner&&u.Commander==ContractFixture.Clerk))||!w.ServiceBonds.Any(b=>b.Subject==ContractFixture.Clerk&&b.Target==ContractFixture.Officer))throw new InvalidDataException("Other-house ownership or explicit mandate differs");
        foreach(var observer in new[]{w.PlayerControl,ContractFixture.Clerk,ContractFixture.Lord,RetainerStart.Lord})if(!w.Evidence.Any(e=>e.Observer==observer&&e.Subject==ContractFixture.Clerk&&e.Claim=="joint-training-command-and-known-camp"&&e.ObservedAt==0&&e.RecordedAt==0&&e.Message==null&&e.Supersedes==null&&w.Knowledge.Any(k=>k.Character==observer&&k.Evidence==e.Id&&k.LearnedAt==0)))throw new InvalidDataException("Party lacks the declared starting agreement");
        var commands=w.Region!.Commands.Where(c=>Remote(w,c.Request)).ToArray();for(int i=0;i<commands.Length;i++)if(commands[i].Request.Supersedes!=(i==0?(EntityId?)null:commands[i-1].Request.Id))throw new InvalidDataException("Nonlinear replacement chain");if(s.Plans.Select(p=>p.Directive).Distinct().Count()!=s.Plans.Length||s.Plans.Length!=commands.Count(c=>c.Result=="applied"))throw new InvalidDataException("Missing/duplicate directive plan");foreach(var p in s.Plans){var c=commands.Single(c=>c.Request.Id==p.Directive);if(c.AppliedAt!=p.At||!p.Units.Select(u=>u.Unit).SequenceEqual(Units))throw new InvalidDataException("Plan lacks recognized directive");for(int i=0;i<p.Units.Length;i++){var u=p.Units[i];var goal=c.Request.Action==RegionalAction.Hold?u.Origin:c.Request.Action==RegionalAction.Retreat?w.Region.Units.Single(x=>x.Id==u.Unit).Home:new FieldPoint(c.Request.A.X+(c.Request.B.X-c.Request.A.X)*i/2,c.Request.A.Y+(c.Request.B.Y-c.Request.A.Y)*i/2);if(u.Goal!=goal||u.Route.Any(l=>l.StartAt<p.At))throw new InvalidDataException("Plan exceeds delegated purpose");RegionalGround.ValidatePath(u.Route,u.Origin,u.Goal,scenery:true,atlas:true);}}
        if(s.Arrivals.Select(r=>r.Directive).Distinct().Count()!=s.Arrivals.Length||w.Messaging.Messages.Count(m=>m.Kind==ArrivalKind)!=s.Arrivals.Length)throw new InvalidDataException("Missing/duplicate arrival report");foreach(var r in s.Arrivals){var p=s.Plans.Single(p=>p.Directive==r.Directive);var m=w.Messaging.Messages.Single(m=>m.Id==r.Message);long earliest=p.Units.SelectMany(u=>u.Route).Select(l=>l.EndAt).DefaultIfEmpty(p.At).Max();if(r.Message!=Message(r.Directive)||r.At<earliest||r.At>w.ElapsedSeconds||m.CreatedAt!=r.At||m.Kind!=ArrivalKind||m.Body!=Body(r)||m.SenderId!=s.Terms.Recipient.Value||m.RecipientId!=s.Terms.Agent.Value||m.CorrelationId!=r.Directive.Value||m.Scope!=ContractFixture.Castle.Value||!r.Units.Select(u=>u.Unit).SequenceEqual(Units))throw new InvalidDataException("Arrival report lacks physical plan/time");foreach(var u in r.Units){var state=w.Region.Units.Single(v=>v.Id==u.Unit);if(u.Position!=p.Units.Single(v=>v.Unit==u.Unit).Goal||u.Heading==new FieldPoint(0,0)||u.Soldiers!=state.InitialSoldiers-w.Region.Losses.Where(l=>l.Unit==u.Unit&&l.At<=r.At).Sum(l=>l.Soldiers)||u.Morale!=state.InitialMorale-w.Region.Losses.Where(l=>l.Unit==u.Unit&&l.At<=r.At).Sum(l=>l.Morale))throw new InvalidDataException("Arrival report changes own unit facts");}}
    }
}
